+package com.example.customers.domain;
+
+import java.io.Serializable;
+import java.text.Normalizer;
+import java.util.Collection;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * The narrowing the user has asked for: a free-text name filter and a set of
+ * statuses.
+ *
+ * <p>A customer matches when it satisfies both parts. The name filter is split
+ * into whitespace-separated terms and every term must occur in either the first
+ * or the last name; matching ignores case and accents in both directions, so
+ * {@code makinen} and {@code MÄKINEN} both find {@code Mäkinen}. An empty name
+ * and an empty set of statuses match everything, so {@link #EMPTY} is the
+ * unfiltered query.
+ *
+ * <p>Instances are immutable and are compared by value, which is what lets the
+ * UI tell one filter from another.
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) implements Serializable {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.strip();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    /** Whether this filter narrows anything down at all. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /** This filter with a different name text. */
+    public CustomerFilter withName(String newName) {
+        return new CustomerFilter(newName, statuses);
+    }
+
+    /** This filter with a different set of statuses. */
+    public CustomerFilter withStatuses(Collection<CustomerStatus> newStatuses) {
+        return new CustomerFilter(name, newStatuses == null ? Set.of() : Set.copyOf(newStatuses));
+    }
+
+    /**
+     * The name filter as normalized terms, all of which have to match. Empty
+     * when no name was entered.
+     */
+    public List<String> nameTerms() {
+        return WHITESPACE.splitAsStream(fold(name))
+                .filter(term -> !term.isEmpty())
+                .toList();
+    }
+
+    /** The selected statuses in {@link CustomerStatus} declaration order. */
+    public List<CustomerStatus> statusesInDeclarationOrder() {
+        // The canonical constructor stores the statuses in an EnumSet, which
+        // iterates in declaration order.
+        return List.copyOf(statuses);
+    }
+
+    /**
+     * This filter as a predicate. The name terms are normalized once, up front,
+     * rather than once per customer.
+     */
+    public Predicate<Customer> asPredicate() {
+        if (isEmpty()) {
+            return customer -> true;
+        }
+        List<String> terms = nameTerms();
+        Set<CustomerStatus> allowed = statuses;
+        return customer -> matchesStatus(customer, allowed) && matchesName(customer, terms);
+    }
+
+    private static boolean matchesStatus(Customer customer, Set<CustomerStatus> allowed) {
+        return allowed.isEmpty() || allowed.contains(customer.status());
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        for (String term : terms) {
+            if (!firstName.contains(term) && !lastName.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /**
+     * Lower-cases text and strips accents, so that {@code Mäkinen},
+     * {@code makinen} and {@code MÄKINEN} all fold to the same thing.
+     */
+    public static String fold(String text) {
+        if (text == null || text.isEmpty()) {
+            return "";
+        }
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
