+        getUI().ifPresent(ui -> ui.getPage().executeJs(
+                "window.history.replaceState(window.history.state, '', window.location.pathname + $0)",
+                queryString()));
+    }
+
+    /** The filter as a query string, {@code ""} when nothing is filtered. */
+    String queryString() {
+        List<String> parameters = new ArrayList<>();
+        if (!filter.name().isEmpty()) {
+            parameters.add(NAME_PARAM + "=" + encode(filter.name()));
+        }
+        if (!filter.statuses().isEmpty()) {
+            parameters.add(STATUS_PARAM + "=" + filter.statusesInDeclarationOrder().stream()
+                    .map(CustomerStatus::name)
+                    .collect(Collectors.joining(STATUS_SEPARATOR)));
+        }
+        return parameters.isEmpty() ? "" : "?" + String.join("&", parameters);
+    }
+
+    private static String encode(String value) {
+        return URLEncoder.encode(value, StandardCharsets.UTF_8).replace("+", "%20");
+    }
+
+    /**
+     * Reads the statuses out of the URL. Accepts both a comma-separated list
+     * and a repeated parameter, and ignores anything that is not a status.
+     */
+    private static Set<CustomerStatus> parseStatuses(List<String> values) {
+        Set<CustomerStatus> statuses = new LinkedHashSet<>();
+        for (String value : values) {
+            for (String name : value.split(STATUS_SEPARATOR)) {
+                String trimmed = name.strip();
+                for (CustomerStatus status : CustomerStatus.values()) {
+                    if (status.name().equalsIgnoreCase(trimmed)) {
+                        statuses.add(status);
+                    }
+                }
+            }
+        }
+        return statuses;
     }

